//! The HLSL 5.0 shell: resource declarations, the uniforms, `ocio_transform` around the op
//! bodies of `gpu/ops.rs` (written once for every language, ROADMAP G6), and the pixel-shader
//! entry point. Nothing here is colour maths.

use super::*;
use crate::gpu_shader_utils::ShaderText;

impl GpuProcessor {
    // =========================================================================
    // HLSL 5.0 Generation
    // =========================================================================

    /// Generates HLSL 5.0 shader code.
    pub(super) fn generate_hlsl(
        &self,
        code: &mut String,
        uniform_bindings: &[Option<OpUniforms>],
        uniforms: &[GpuUniform],
    ) {
        let mut st = ShaderText::new();

        // Texture declarations
        st.line("// HLSL 5.0 Generated by vfx-ocio");
        st.new_line();

        // Input texture
        st.line("Texture2D u_inputTexture : register(t0);");
        st.line("SamplerState u_inputSampler : register(s0);");
        st.new_line();

        // LUT texture declarations
        for (idx, tex) in self.textures.iter().enumerate() {
            match tex.texture_type {
                GpuTextureType::Texture1D => {
                    st.linef(format!("Texture1D {} : register(t{});", tex.name, idx + 1));
                    st.linef(format!(
                        "SamplerState {}_sampler : register(s{});",
                        tex.name,
                        idx + 1
                    ));
                }
                GpuTextureType::Texture2D => {
                    st.linef(format!("Texture2D {} : register(t{});", tex.name, idx + 1));
                    st.linef(format!(
                        "SamplerState {}_sampler : register(s{});",
                        tex.name,
                        idx + 1
                    ));
                }
                GpuTextureType::Texture3D => {
                    st.linef(format!("Texture3D {} : register(t{});", tex.name, idx + 1));
                    st.linef(format!(
                        "SamplerState {}_sampler : register(s{});",
                        tex.name,
                        idx + 1
                    ));
                }
            }
        }
        st.new_line();

        // Uniform declarations
        self.emit_uniform_decls_hlsl(&mut st, uniforms);

        // Helper functions (the curve ops' evaluators, gpu/ops.rs).
        for line in ops::helpers(self, &dialect::HLSL, uniform_bindings) {
            st.linef(line);
        }

        // Vertex shader output / pixel shader input
        st.line("struct PSInput {");
        st.indent();
        st.line("float4 position : SV_POSITION;");
        st.line("float2 texCoord : TEXCOORD0;");
        st.dedent();
        st.line("};");
        st.new_line();

        // Color transform function
        st.line("float4 ocio_transform(float4 color) {");
        st.indent();

        for line in ops::body(self, &dialect::HLSL, uniform_bindings) {
            st.linef(line);
        }

        st.line("return color;");
        st.dedent();
        st.line("}");
        st.new_line();

        // Pixel shader main
        st.line("float4 main(PSInput input) : SV_TARGET {");
        st.indent();
        st.line("float4 color = u_inputTexture.Sample(u_inputSampler, input.texCoord);");
        st.line("return ocio_transform(color);");
        st.dedent();
        st.line("}");

        code.push_str(st.code());
    }
}
